#if UNITY_EDITOR
using System.Collections.Generic;
using System.Linq;
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by vfx-shader. The prefab is rebuilt from this script: edit here, not in the Inspector.
    // Plan: Docs/VFX/WindTornado/Plan.md (v3)
    //
    // v3 follows rpg-game's Stupid_Tornado_Projectile layer by layer (reference copy: Assets/VFX/_Imported/RpgTornado/, render + full dump of every
    // module: Docs/VFX/WindTornado/ref_Stupid_Tornado_Projectile*). Their numbers are kept, multiplied by K (size / speed) to fit a ~3.6 m standing column.
    // How the reference works (read from the prefab, the Shader Graph and the textures):
    //  * Wind  : fbx_fx_cylinder_03 (open ring, ~340 deg, radius 0.59 m, height 0.27 m, UV 0..1 round and up) x size 5-7, tilted 70-110 deg, spinning
    //            3 rev/s easing out, 0.35-0.5 s life. Shader `Fx_dissolve_particle_apb` (Built-in target of the Shader Graph, imported RpgGame/ShaderGraph) on a
    //            channel-packed sheet (R = tone, G = dissolve / highlight field, B = UV wobble, A = alpha): Custom1 = (dissolve, edge sharpness, wobble, -),
    //            Custom2 = highlight colour, body colour = Start Color (06FFDF). Cells 14-15 of Tex_fx_elements_set_01 (4x4).
    //  * Tubes : Tornado_vertical (r 0.32, h 0.29) stretched Z, rising 8 m/s and widening r 0.27 -> 2.9 m, Additive, Wind01 wisps.
    //  * Mist / Ground mist: Dust01 soft puffs (column going up, flat spread at the foot).  Smoke: sheet cell 10 puffs, world space.
    //  * Sharp ring: splash sheet cell 8 (lens) on the same ring mesh, brighter.  Bits: small blue debris (8x8 cell 19).
    // Deviation (a projectile spawns for 1.5 s and dies off; this is a standing 3.6 s effect): emission is ramp-up / hold / ramp-down instead of
    // 1 -> 0. Lines marked [ref] are straight from the dump.
    public static class WindTornadoBuild
    {
        const string Root = "Assets/VFX/WindTornado";
        const string Ref = "Assets/VFX/_Imported/RpgTornado/_Game/Resources_moved/";
        const string MeshRing = Ref + "Models/fbx_fx_cylinder_03.FBX";
        const string MeshTube = Ref + "Models/Tornado_vertical.fbx";
        const string SheetElements = Ref + "Textures/Tex_fx_elements_set_01.tga";   // channel-packed sheet; not in Library (unclassified)
        const string SheetSplash = "Assets/Library/impact/flipbook/impact_flipbook_014.tga";           // = Tex_fx_splash_set
        const string TexDust = "Assets/Library/smoke/soft/smoke_soft_002.png";                  // = Dust01
        const string TexWind = "Assets/Library/trail/ribbon/trail_ribbon_015.png";                    // = Wind01
        const string ShGraph = "Shader Graphs/Fx_dissolve_particle_apb";

        const float Emit = 2.6f;       // emission window (s); longest life 1.3 s -> ends ~3.9 s
        const float K = 0.5f;          // scale of the reference numbers

        static readonly Color Teal = new Color32(0x06, 0xFF, 0xDF, 0xFF);              // [ref] start colour of the wind rings

        [MenuItem("VFX/WindTornado/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Prefabs", "Scenes");
            foreach (var n in new[] { "Spiral", "Inner", "Streaks", "Gust", "Dust", "Body", "Rings", "Mist", "Ground", "Wind", "Tubes", "FogUp", "FogDown", "Smoke", "Sharp", "Bits" })
                AssetDatabase.DeleteAsset(Root + "/Materials/M_WindTornado_" + n + ".mat");

            var ring = LoadMesh(MeshRing);
            var tube = LoadMesh(MeshTube);
            var elements = Tex(SheetElements);
            var splash = Tex(SheetSplash);
            var dust = Tex(TexDust);
            var wind = Tex(TexWind);

            string M(string n) => Root + "/Materials/M_WindTornado_" + n + ".mat";
            var mWind = Graph(M("Wind"), elements, 3025, softParticles: false);
            var mSharp = Graph(M("Sharp"), splash, 3027, softParticles: true);
            var mSmoke = Graph(M("Smoke"), elements, 3025, softParticles: false);
            var mBits = Graph(M("Bits"), elements, 3025, softParticles: false);
            var mTubes = Material(M("Tubes"), VfxBlend.Additive, wind);
            var mFogUp = Material(M("FogUp"), VfxBlend.Alpha, dust);
            var mFogDown = Material(M("FogDown"), VfxBlend.Additive, dust);

            // ---- L1 Wind (prefab root): rings spinning round the axis, eroding as they live
            var root = new GameObject("VFX_WindTornado");
            var ps = ParticleOn(root, mWind, Emit, 1f, Teal);
            {
                var main = ps.main; main.maxParticles = 20;
                main.startLifetime = new ParticleSystem.MinMaxCurve(0.35f, 0.5f);                                           // [ref]
                main.startSpeed = new ParticleSystem.MinMaxCurve(4f * K, 6f * K);                                           // [ref]
                main.startSize = new ParticleSystem.MinMaxCurve(5f * K, 7f * K);                                            // [ref]
                main.startRotation3D = true;
                main.startRotationX = new ParticleSystem.MinMaxCurve(1.222f, 1.92f);                                        // [ref] 70-110 deg
                main.startRotationY = new ParticleSystem.MinMaxCurve(0f, 2f * Mathf.PI);
                main.startRotationZ = 0f;
                Rate(ps, 25f);
                var shape = ps.shape; shape.enabled = true; shape.shapeType = ParticleSystemShapeType.Cone; shape.radius = 0.0001f; shape.angle = 0f; shape.rotation = new Vector3(-90f, 0f, 0f);
                Spin(ps, 18.85f);                                                                                           // [ref] 3 rev/s, easing to 0
                SizeXYZ(ps, new[] { 0f, 0f, 0.14f, 0.38f, 1f, 1f }, 1f, new[] { 0f, 0f, 0.15f, 0.61f, 1f, 1f }, 1.5f);   // [ref]
                AlphaOverLifetime(ps, 0f, 1f, 1f, 0f);                                                                      // [ref]
                Tsa(ps, 4, 4, 0.875f, 1f);                                                                                  // [ref] cells 14-15
                SetGraphRenderer(ps, ring, 5, mesh_: true);
                GraphData(ps, dissolve: new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 0f, 1f, 1f)), sharp: new ParticleSystem.MinMaxCurve(20f), wobble: new ParticleSystem.MinMaxCurve(0f),
                    w: 50f, custom2: Color.white);
            }

            // ---- L2 Sharp ring: brighter lens-shaped rings that rise (their sharp_circle; splash sheet cell 8)
            var sharp = Particle(root.transform, "L2_SharpRing", mSharp, Emit, 1f, Color.white);
            {
                var main = sharp.main; main.maxParticles = 20;
                main.startLifetime = new ParticleSystem.MinMaxCurve(0.2f, 0.35f);                                           // [ref]
                main.startSpeed = 0f;
                main.startSize = new ParticleSystem.MinMaxCurve(3f * K, 5f * K);
                main.startRotation3D = true;
                main.startRotationX = new ParticleSystem.MinMaxCurve(1.222f, 1.92f);
                main.startRotationY = new ParticleSystem.MinMaxCurve(0f, 2f * Mathf.PI);
                main.startRotationZ = 0f;
                Rate(sharp, 25f);
                var shape = sharp.shape; shape.enabled = true; shape.shapeType = ParticleSystemShapeType.Box; shape.position = new Vector3(0f, 0.5f * K, 0f); shape.scale = new Vector3(0.01f, 1f, 0.01f);
                var v = sharp.velocityOverLifetime; v.enabled = true; v.space = ParticleSystemSimulationSpace.Local;       // [ref] lin y 5..1
                v.x = new ParticleSystem.MinMaxCurve(0f, 0f); v.y = new ParticleSystem.MinMaxCurve(1f * K, 5f * K); v.z = new ParticleSystem.MinMaxCurve(0f, 0f);
                Spin(sharp, 18.85f);
                SizeXYZ(sharp, new[] { 0f, 0.5f, 1f, 1f }, 1f, new[] { 0f, 0.67f, 1f, 0f }, 0.5f);                           // [ref]
                Tsa(sharp, 3, 6, 0.444f, 0.444f);                                                                           // [ref] cell 8
                SetGraphRenderer(sharp, ring, 6, mesh_: true);
                GraphData(sharp, dissolve: new ParticleSystem.MinMaxCurve(0f), sharp: new ParticleSystem.MinMaxCurve(0f), wobble: new ParticleSystem.MinMaxCurve(0f),
                    w: 3f, custom2: Color.white);
            }

            // ---- L3 Tubes: thin wind tubes that rise and widen (their wind_up), Additive, Wind01 wisps
            var tubes = Particle(root.transform, "L3_Tubes", mTubes, 1f, 1f, Color.white);
            {
                tubes.transform.localRotation = Quaternion.Euler(270f, 0f, 0f);                                             // [ref]
                var main = tubes.main; main.duration = Emit; main.maxParticles = 20;
                main.startLifetime = 1f;
                main.startSpeed = 8f * K;                                                                                   // [ref]
                main.startSize3D = true; main.startSizeX = 3f * K; main.startSizeY = 3f * K; main.startSizeZ = 15f * K;     // [ref]
                main.startRotation = new ParticleSystem.MinMaxCurve(0f, 2f * Mathf.PI);
                main.startColor = new ParticleSystem.MinMaxGradient((Color)new Color32(0x69, 0xB4, 0xFF, 0xFF), (Color)new Color32(0xDC, 0xF2, 0xFF, 0xFF));   // [ref]
                Rate(tubes, 10f);
                var rot = tubes.rotationOverLifetime; rot.enabled = true; rot.separateAxes = false; rot.z = 6.981f;         // [ref]
                SizeXYZ(tubes, new[] { 0f, 0.09f, 1f, 1f }, 3f, new[] { 0f, 0.18f, 1f, 0.74f }, 1f);                         // [ref]
                AlphaOverLifetime(tubes, 0f, 0f, 0.14f, 0.59f, 0.49f, 0.24f, 1f, 0f);                                      // [ref]
                SetMeshOnly(tubes, tube, 4);
            }

            // ---- L4 Mist column going up (their fog_up): Dust01 puffs, Alpha Blended, thin slice of a circle
            var fogUp = Particle(root.transform, "L4_MistUp", mFogUp, 1.3f, 1f, Color.white);
            {
                fogUp.transform.localPosition = new Vector3(0f, 0.35f * K, 0f);                                             // [ref]
                fogUp.transform.localRotation = Quaternion.Euler(0f, 270f, 90f);                                            // [ref]
                var main = fogUp.main; main.duration = Emit; main.maxParticles = 60;
                main.startLifetime = 1.3f; main.startSpeed = 5f * K; main.startSize = 5f * K;
                main.startRotation = new ParticleSystem.MinMaxCurve(0f, 2f * Mathf.PI);
                main.startColor = new Color(1f, 1f, 1f, 0.65f);                                                             // [ref] FFFFFFA5
                Rate(fogUp, 10f);
                var shape = fogUp.shape; shape.enabled = true; shape.shapeType = ParticleSystemShapeType.Circle; shape.radius = 0.0001f; shape.radiusThickness = 1f; shape.arc = 7.5f;
                var rot = fogUp.rotationOverLifetime; rot.enabled = true; rot.separateAxes = false; rot.z = new ParticleSystem.MinMaxCurve(1.745f, -1.745f);
                var sol = fogUp.sizeOverLifetime; sol.enabled = true; sol.size = new ParticleSystem.MinMaxCurve(1.5f, AnimCurve(0f, 0.11f, 0.67f, 0.52f, 1f, 1f));
                AlphaOverLifetime(fogUp, 0f, 0f, 0.11f, 1f, 0.52f, 0.49f, 1f, 0f);
                fogUp.GetComponent<ParticleSystemRenderer>().sortingOrder = 3;
            }

            // ---- L5 Ground mist (their fog_down; theirs is a Horizontal Billboard: here Billboard + alignment Local, laid flat by the GameObject)
            var fogDown = Particle(root.transform, "L5_MistFoot", mFogDown, 0.7f, 1f, Color.white);
            {
                fogDown.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
                var main = fogDown.main; main.duration = Emit; main.maxParticles = 30;
                main.startLifetime = 0.7f; main.startSpeed = 0f; main.startSize = new ParticleSystem.MinMaxCurve(8f * K, 10f * K);
                main.startRotation = new ParticleSystem.MinMaxCurve(0f, 2f * Mathf.PI);
                main.startColor = new ParticleSystem.MinMaxGradient((Color)new Color32(0xAA, 0xB2, 0xFD, 0x9F), (Color)new Color32(0xAC, 0xF9, 0xFF, 0x76));    // [ref]
                Rate(fogDown, 10f);
                var rot = fogDown.rotationOverLifetime; rot.enabled = true; rot.separateAxes = false; rot.z = new ParticleSystem.MinMaxCurve(-0.873f, -2.618f);
                SizeOverLifetime(fogDown, 0f, 1f, 1f, 0f);                                                                  // [ref]
                AlphaOverLifetime(fogDown, 0f, 0f, 0.46f, 0.57f, 1f, 0f);                                                   // [ref]
                var r = fogDown.GetComponent<ParticleSystemRenderer>(); r.alignment = ParticleSystemRenderSpace.Local; r.sortingOrder = 1;
            }

            // ---- L6 Smoke (their smoke_trail): sheet cell 10 puffs through the graph, world space, grey, drifting up and out
            var smoke = Particle(root.transform, "L6_Smoke", mSmoke, Emit, 1f, Color.white);
            {
                var main = smoke.main; main.maxParticles = 30;
                main.startLifetime = new ParticleSystem.MinMaxCurve(0.5f, 0.7f);
                main.startSpeed = new ParticleSystem.MinMaxCurve(3f * K, 5f * K);
                main.startSize = new ParticleSystem.MinMaxCurve(3.5f * K, 5f * K);
                main.startRotation = new ParticleSystem.MinMaxCurve(0f, 2f * Mathf.PI);
                main.gravityModifier = new ParticleSystem.MinMaxCurve(-1f, -0.5f);
                main.simulationSpace = ParticleSystemSimulationSpace.World;                                                 // [ref]
                Rate(smoke, 30f);
                var shape = smoke.shape; shape.enabled = true; shape.shapeType = ParticleSystemShapeType.Cone; shape.radius = 2.2f * K; shape.radiusThickness = 0.3f; shape.angle = 45f; shape.rotation = new Vector3(-90f, 0f, 0f);
                SizeOverLifetime(smoke, 0f, 0f, 0.13f, 0.52f, 1f, 1f);                                                      // [ref]
                var col = smoke.colorOverLifetime; col.enabled = true;
                var g = new Gradient();
                g.SetKeys(new[] { new GradientColorKey((Color)new Color32(0xBA, 0xBA, 0xBA, 0xFF), 0f), new GradientColorKey(Color.white, 1f) },
                          new[] { new GradientAlphaKey(0.08f, 0f), new GradientAlphaKey(0f, 1f) });                         // [ref]
                col.color = g;
                Tsa(smoke, 4, 4, 0.625f, 0.625f);                                                                           // [ref] cell 10
                SetGraphRenderer(smoke, null, 2, mesh_: false);
                GraphData(smoke, dissolve: new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 0f, 1f, 1f)), sharp: new ParticleSystem.MinMaxCurve(20f, AnimCurve(0f, 0f, 1f, 1f)),
                    wobble: new ParticleSystem.MinMaxCurve(0.1f, AnimCurve(0f, 0f, 1f, -1f)), w: 3f, custom2: null);
            }

            // ---- L7 Bits: tiny blue debris whirled round the foot (their particle_bright; 8x8 cell 19)
            var bits = Particle(root.transform, "L7_Bits", mBits, Emit, 1f, Color.white);
            {
                var main = bits.main; main.maxParticles = 20;
                main.startLifetime = new ParticleSystem.MinMaxCurve(0.3f, 0.5f);
                main.startSpeed = new ParticleSystem.MinMaxCurve(1f * K, 13f * K);
                main.startSize = new ParticleSystem.MinMaxCurve(0.3f, 0.5f);                                                // [ref] (small: not scaled)
                main.startRotation = new ParticleSystem.MinMaxCurve(0f, 2f * Mathf.PI);
                main.startColor = (Color)new Color32(0x00, 0x80, 0xFF, 0xFF);                                               // [ref]
                Rate(bits, 30f);
                var shape = bits.shape; shape.enabled = true; shape.shapeType = ParticleSystemShapeType.Cone; shape.radius = 2f * K; shape.radiusThickness = 0.5f; shape.angle = 45f; shape.rotation = new Vector3(-90f, 0f, 0f);
                var v = bits.velocityOverLifetime; v.enabled = true; v.space = ParticleSystemSimulationSpace.Local;         // [ref] orbital Y -0.5 -> 0 (x20)
                ParticleSystem.MinMaxCurve Flat(float m) => new ParticleSystem.MinMaxCurve(m, AnimCurve(0f, 1f, 1f, 1f));
                var zero = new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 0f, 1f, 0f));
                v.x = zero; v.y = zero; v.z = zero; v.radial = zero; v.speedModifier = Flat(1f);
                v.orbitalX = Flat(1f); v.orbitalY = new ParticleSystem.MinMaxCurve(20f, AnimCurve(0f, -0.5f, 1f, 0f)); v.orbitalZ = Flat(1f);
                SizeOverLifetime(bits, 0f, 0f, 0.05f, 1f, 0.1f, 0.43f, 0.15f, 0.88f, 0.2f, 0.34f, 0.26f, 0.76f, 0.32f, 0.23f, 0.37f, 0.63f, 0.43f, 0.17f, 0.51f, 0.54f,
                    0.55f, 0.09f, 0.61f, 0.46f, 0.66f, 0.05f, 0.72f, 0.38f, 0.79f, 0.03f, 0.83f, 0.27f, 0.89f, 0f, 0.94f, 0.16f, 1f, 0f);           // [ref] flicker
                Tsa(bits, 8, 8, 0.297f, 0.297f);                                                                            // [ref] cell 19
                SetGraphRenderer(bits, null, 7, mesh_: false);
                GraphData(bits, dissolve: new ParticleSystem.MinMaxCurve(0f), sharp: new ParticleSystem.MinMaxCurve(0f),
                    wobble: new ParticleSystem.MinMaxCurve(0.1f, AnimCurve(0f, 0f, 1f, -1f)), w: 3f, custom2: Color.white);
            }

            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_WindTornado.prefab");
            float d = 7.5f, el = 40f * Mathf.Deg2Rad;
            var cam = new Vector3(0f, 1.2f + d * Mathf.Sin(el), -d * Mathf.Cos(el));    // 3/4 view, 40 deg down (project default)
            Finish(prefab, Root, "WindTornado", new[] { 0.2f, 0.5f, 1.0f, 1.8f, 2.6f, 3.4f }, cam, new Vector3(0f, 1.2f, 0f));
        }

        public static void BuildBatch() => RunBatch(Build);

        // Material of the reference Shader Graph (Built-in target). Property names are the graph's reference names (read from the reference materials).
        static Material Graph(string path, Texture2D sheet, int queue, bool softParticles)
        {
            var m = Material(path, VfxBlend.Alpha, null, ShGraph);
            m.SetTexture("Main_tex", sheet); m.SetTextureScale("Main_tex", Vector2.one); m.SetTextureOffset("Main_tex", Vector2.zero);
            m.SetFloat("Vector1_930B327D", -10f);                 // Highlight_Min [ref]
            m.SetFloat("Vector1_270105AC", -2f);                  // Highlight_Max [ref]
            m.SetFloat("Boolean_9C0948F4", softParticles ? 1f : 0f);   // Use SoftParticleFactor?
            m.SetFloat("Vector1_2C5A3101", 1f);                   // Emission_Power
            m.renderQueue = queue;
            EditorUtility.SetDirty(m);
            return m;
        }

        // [ref] stream order: Position, Normal, Color, UV, UV2, Custom1XYZW, Custom2XYZW (UV channel 1 = Custom1, channel 2 = Custom2 in the graph)
        static void SetGraphRenderer(ParticleSystem ps, Mesh mesh, int order, bool mesh_)
        {
            var r = ps.GetComponent<ParticleSystemRenderer>();
            if (mesh_) { r.renderMode = ParticleSystemRenderMode.Mesh; r.mesh = mesh; r.alignment = ParticleSystemRenderSpace.Local; }
            else { r.renderMode = ParticleSystemRenderMode.Billboard; r.alignment = ParticleSystemRenderSpace.View; }
            r.sortingOrder = order;
            r.enableGPUInstancing = false;
            r.SetActiveVertexStreams(new List<ParticleSystemVertexStream>
            {
                ParticleSystemVertexStream.Position, ParticleSystemVertexStream.Normal, ParticleSystemVertexStream.Color, ParticleSystemVertexStream.UV,
                ParticleSystemVertexStream.UV2, ParticleSystemVertexStream.Custom1XYZW, ParticleSystemVertexStream.Custom2XYZW
            });
        }

        static void SetMeshOnly(ParticleSystem ps, Mesh mesh, int order)
        {
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.renderMode = ParticleSystemRenderMode.Mesh; r.mesh = mesh; r.alignment = ParticleSystemRenderSpace.Local; r.sortingOrder = order;
        }

        // Custom1 = (dissolve, edge sharpness, UV wobble, unused); Custom2 = highlight colour (null = module off, as in the reference)
        static void GraphData(ParticleSystem ps, ParticleSystem.MinMaxCurve dissolve, ParticleSystem.MinMaxCurve sharp, ParticleSystem.MinMaxCurve wobble, float w, Color? custom2)
        {
            var cd = ps.customData; cd.enabled = true;
            cd.SetMode(ParticleSystemCustomData.Custom1, ParticleSystemCustomDataMode.Vector);
            cd.SetVectorComponentCount(ParticleSystemCustomData.Custom1, 4);
            cd.SetVector(ParticleSystemCustomData.Custom1, 0, dissolve);
            cd.SetVector(ParticleSystemCustomData.Custom1, 1, sharp);
            cd.SetVector(ParticleSystemCustomData.Custom1, 2, wobble);
            cd.SetVector(ParticleSystemCustomData.Custom1, 3, new ParticleSystem.MinMaxCurve(w));
            if (custom2.HasValue)
            {
                cd.SetMode(ParticleSystemCustomData.Custom2, ParticleSystemCustomDataMode.Color);
                cd.SetColor(ParticleSystemCustomData.Custom2, new ParticleSystem.MinMaxGradient(custom2.Value));
            }
        }

        static void Tsa(ParticleSystem ps, int x, int y, float f0, float f1)
        {
            var ts = ps.textureSheetAnimation; ts.enabled = true;
            ts.mode = ParticleSystemAnimationMode.Grid; ts.numTilesX = x; ts.numTilesY = y; ts.animation = ParticleSystemAnimationType.WholeSheet;
            ts.frameOverTime = new ParticleSystem.MinMaxCurve(f0, f1); ts.cycleCount = 1;
        }

        // Rotation over lifetime Z: speed x curve (1 -> 0); x, y are flat 0 curves (all axes must share one mode or Unity ignores the module)
        static void Spin(ParticleSystem ps, float speed)
        {
            var rot = ps.rotationOverLifetime; rot.enabled = true; rot.separateAxes = true;
            rot.x = new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 0f, 1f, 0f));
            rot.y = new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 0f, 1f, 0f));
            rot.z = new ParticleSystem.MinMaxCurve(speed, AnimCurve(0f, 1f, 1f, 0f));
        }

        // Size over lifetime with separate axes: x = y = curve xy (multiplier xyMul), z = curve z (zMul)
        static void SizeXYZ(ParticleSystem ps, float[] xy, float xyMul, float[] z, float zMul)
        {
            var s = ps.sizeOverLifetime; s.enabled = true; s.separateAxes = true;
            s.x = new ParticleSystem.MinMaxCurve(xyMul, AnimCurve(xy));
            s.y = new ParticleSystem.MinMaxCurve(xyMul, AnimCurve(xy));
            s.z = new ParticleSystem.MinMaxCurve(zMul, AnimCurve(z));
        }

        // Standing effect: ramp up 0.3 s, hold, ramp down (curve over the emission window)
        static void Rate(ParticleSystem ps, float perSecond)
        {
            var em = ps.emission;
            em.SetBursts(new ParticleSystem.Burst[0]);
            em.rateOverTime = new ParticleSystem.MinMaxCurve(perSecond, AnimCurve(0f, 0.2f, 0.1f, 1f, 0.75f, 1f, 1f, 0f));
        }

        static Texture2D Tex(string path)
        {
            var t = AssetDatabase.LoadAssetAtPath<Texture2D>(path);
            if (t == null) throw new System.InvalidOperationException("Texture missing: " + path);
            return t;
        }

        static Mesh LoadMesh(string path)
        {
            var m = AssetDatabase.LoadAssetAtPath<Mesh>(path);
            if (m == null) throw new System.InvalidOperationException("Mesh missing: " + path);
            Debug.Log("[WindTornado] mesh " + path + " bounds " + m.bounds.size);
            return m;
        }
    }
}
#endif
